import test from "node:test";
import assert from "node:assert/strict";
import {apply, planner} from "./replay.mjs";

const catalog = () => ({default: 5, studios: new Map([["orchid", 8], ["small", 2]])});
const request = (id, units, tenant = "orchid", day = "2025-04-02") =>
  ({id, units, tenant, day});
function desk(service = "studio") {
  const dispatch = planner(catalog());
  return (action, fields = {}) => apply(dispatch, {service, action, ...fields});
}

test("Studio uses higher and lower allocations, with a default for unlisted tenants", () => {
  const run = desk();
  assert.deepEqual(run("book", request("orchid", 8)),
    {status: "booked", id: "orchid", remaining: 0});
  assert.deepEqual(run("book", request("small-full", 3, "small")),
    {status: "full", id: "small-full", remaining: 2});
  assert.deepEqual(run("book", request("small", 2, "small")),
    {status: "booked", id: "small", remaining: 0});
  assert.deepEqual(run("book", request("default-full", 6, "other")),
    {status: "full", id: "default-full", remaining: 5});
  assert.deepEqual(run("book", request("default", 5, "other")),
    {status: "booked", id: "default", remaining: 0});
});

test("Studio accounts by tenant and day, and cancellation releases capacity", () => {
  const run = desk();
  run("book", request("first", 6));
  assert.deepEqual(run("book", request("second", 3)),
    {status: "full", id: "second", remaining: 2});
  assert.equal(run("book", request("tomorrow", 8, "orchid", "2025-04-03")).status, "booked");
  assert.equal(run("book", request("other", 5, "other")).status, "booked");
  assert.deepEqual(run("usage", {tenant: "orchid", day: "2025-04-02"}), {units: 6});
  assert.equal(run("cancel", {id: "first"}).status, "cancelled");
  assert.equal(run("cancel", {id: "first"}).status, "replay");
  assert.deepEqual(run("book", request("second", 3)),
    {status: "booked", id: "second", remaining: 5});
  assert.deepEqual(run("usage", {tenant: "orchid", day: "2025-04-02"}), {units: 3});
});

test("Studio checks replay, conflict and cancelled IDs before capacity", () => {
  const run = desk();
  const original = request("original", 8);
  run("book", original);
  const snapshot = run("summary");
  assert.equal(run("book", original).status, "replay");
  assert.equal(run("book", {...original, units: 9}).status, "conflict");
  assert.equal(run("book", request("rejected", 1)).status, "full");
  assert.deepEqual(run("summary"), snapshot);
  assert.equal(run("lookup", {id: "rejected"}), null);
  run("cancel", {id: "original"});
  run("book", request("replacement", 8));
  assert.equal(run("book", original).status, "cancelled");
  assert.equal(run("book", {...original, tenant: "other"}).status, "conflict");
});

test("Studio imports bypass admission but count toward subsequent bookings", () => {
  const run = desk();
  const imported = request("backfill", 10);
  assert.equal(run("import", imported).status, "imported");
  assert.equal(run("book", imported).status, "replay");
  assert.deepEqual(run("book", request("new", 1)),
    {status: "full", id: "new", remaining: 0});
  run("cancel", {id: "backfill"});
  assert.deepEqual(run("book", request("new", 1)),
    {status: "booked", id: "new", remaining: 7});
});

test("Studio renewals inherit tenant and units, share admission and preserve replay semantics", () => {
  const run = desk();
  run("book", request("previous", 7));
  const renewal = {previous: "previous", id: "renewed", day: "2025-05-02", tenant: "other"};
  assert.deepEqual(run("renew", renewal), {status: "booked", id: "renewed", remaining: 1});
  assert.equal(run("lookup", {id: "renewed"}).tenant, "orchid");
  assert.equal(run("renew", renewal).status, "replay");
  assert.equal(run("renew", {...renewal, units: 8}).status, "conflict");
  assert.deepEqual(run("renew", {...renewal, id: "too-large", units: 2}),
    {status: "full", id: "too-large", remaining: 1});
  assert.deepEqual(run("renew", {...renewal, id: "extra", units: 1}),
    {status: "booked", id: "extra", remaining: 0});
  run("cancel", {id: "renewed"});
  assert.equal(run("renew", renewal).status, "cancelled");
  run("cancel", {id: "previous"});
  assert.deepEqual(run("renew", {...renewal, id: "missing"}),
    {status: "missing", id: "previous"});
});

test("Renewals use lower and default caps and retain input validation", () => {
  const run = desk();
  for (const [tenant, units] of [["small", 2], ["other", 5]]) {
    run("book", request(tenant, units, tenant));
    const renewal = {previous: tenant, id: `${tenant}-next`, day: "2025-05-02"};
    assert.deepEqual(run("renew", {...renewal, units: units + 1}),
      {status: "full", id: renewal.id, remaining: units});
    assert.deepEqual(run("renew", renewal),
      {status: "booked", id: renewal.id, remaining: 0});
    assert.deepEqual(run("renew", {...renewal, units: 0}), {status: "invalid", field: "units"});
    assert.deepEqual(run("renew", {...renewal, day: "2025-02-30"}), {status: "invalid", field: "day"});
  }
  assert.deepEqual(run("book", request("invalid", 0)), {status: "invalid", field: "units"});
});

test("Archive retains the catalog default for direct bookings and renewals", () => {
  const dispatch = planner(catalog());
  const run = (service, action, fields) => dispatch({service, action, ...fields});
  assert.equal(run("studio", "book", request("same-id", 8)).status, "booked");
  assert.deepEqual(run("archive", "book", request("too-large", 7)),
    {status: "full", id: "too-large", remaining: 5});
  assert.equal(run("archive", "book", request("same-id", 5)).status, "booked");
  assert.deepEqual(run("archive", "renew", {previous: "same-id", id: "large-renewal", day: "2025-05-02", units: 6}),
    {status: "full", id: "large-renewal", remaining: 5});
  assert.deepEqual(run("archive", "renew", {previous: "same-id", id: "renewal", day: "2025-05-02"}),
    {status: "booked", id: "renewal", remaining: 0});
  assert.equal(run("archive", "book", request("small", 5, "small")).status, "booked");
});
